  "inlineSchema": "// KHOJ Database Schema\n// Run: npx prisma migrate dev\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────\nenum Role {\n  USER\n  ARTISAN\n  ADMIN\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n}\n\nenum ContentType {\n  CRAFT\n  FOOD\n  FESTIVAL\n  COMMUNITY\n  MUSIC\n  ARTISAN\n  WORKSHOP\n}\n\n// ─── Users ───────────────────────────────────────────────\nmodel User {\n  id               String    @id @default(cuid())\n  firstName        String\n  lastName         String\n  email            String    @unique\n  passwordHash     String\n  role             Role      @default(USER)\n  avatar           String?\n  bio              String?\n  resetToken       String?\n  resetTokenExpiry DateTime?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  artisan        Artisan?\n  bookings       Booking[]\n  collections    Collection[]\n  journeys       Journey[]\n  journals       JournalEntry[]\n  compassResults AiCompassResult[]\n\n  @@map(\"users\")\n}\n\n// ─── Cultural Content ────────────────────────────────────\nmodel Community {\n  id          String   @id @default(cuid())\n  name        String\n  slug        String   @unique\n  region      String\n  population  Int?\n  language    String?\n  description String\n  imageUrl    String?\n  tags        String[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"communities\")\n}\n\nmodel Craft {\n  id          String    @id @default(cuid())\n  name        String\n  slug        String    @unique\n  origin      String\n  materials   String[]\n  description String\n  imageUrl    String?\n  tags        String[]\n  artisans    Artisan[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@map(\"crafts\")\n}\n\nmodel Food {\n  id          String   @id @default(cuid())\n  name        String\n  slug        String   @unique\n  region      String\n  ingredients String[]\n  description String\n  imageUrl    String?\n  tags        String[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"foods\")\n}\n\nmodel Festival {\n  id          String   @id @default(cuid())\n  name        String\n  slug        String   @unique\n  month       String\n  location    String\n  description String\n  imageUrl    String?\n  tags        String[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"festivals\")\n}\n\nmodel Music {\n  id          String   @id @default(cuid())\n  name        String\n  slug        String   @unique\n  genre       String\n  instruments String[]\n  description String\n  imageUrl    String?\n  tags        String[]\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"music\")\n}\n\n// ─── Artisans & Workshops ────────────────────────────────\nmodel Artisan {\n  id         String     @id @default(cuid())\n  userId     String     @unique\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  speciality String\n  location   String\n  experience Int // years\n  bio        String?\n  crafts     Craft[]\n  workshops  Workshop[]\n  createdAt  DateTime   @default(now())\n  updatedAt  DateTime   @updatedAt\n\n  @@map(\"artisans\")\n}\n\nmodel Workshop {\n  id          String    @id @default(cuid())\n  artisanId   String\n  artisan     Artisan   @relation(fields: [artisanId], references: [id], onDelete: Cascade)\n  title       String\n  description String\n  location    String\n  duration    Int // in hours\n  maxSlots    Int\n  price       Float // display only — no payment\n  imageUrl    String?\n  tags        String[]\n  isActive    Boolean   @default(true)\n  bookings    Booking[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@map(\"workshops\")\n}\n\n// ─── Bookings ────────────────────────────────────────────\nmodel Booking {\n  id           String        @id @default(cuid())\n  userId       String\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  workshopId   String\n  workshop     Workshop      @relation(fields: [workshopId], references: [id], onDelete: Cascade)\n  status       BookingStatus @default(PENDING)\n  scheduledAt  DateTime\n  participants Int           @default(1)\n  notes        String?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  @@map(\"bookings\")\n}\n\n// ─── Collections ─────────────────────────────────────────\nmodel Collection {\n  id          String           @id @default(cuid())\n  userId      String\n  user        User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title       String\n  description String?\n  isPublic    Boolean          @default(false)\n  items       CollectionItem[]\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  @@map(\"collections\")\n}\n\nmodel CollectionItem {\n  id           String      @id @default(cuid())\n  collectionId String\n  collection   Collection  @relation(fields: [collectionId], references: [id], onDelete: Cascade)\n  contentType  ContentType\n  contentId    String\n  note         String?\n  createdAt    DateTime    @default(now())\n\n  @@unique([collectionId, contentType, contentId])\n  @@map(\"collection_items\")\n}\n\n// ─── Journeys ────────────────────────────────────────────\nmodel Journey {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String\n  summary   String?\n  days      Json // AI-generated day-by-day itinerary\n  duration  Int // days\n  startCity String\n  budget    String\n  interests String[]\n  isPublic  Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"journeys\")\n}\n\n// ─── Journals ────────────────────────────────────────────\nmodel JournalEntry {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title     String\n  content   String\n  mood      String?\n  location  String?\n  photos    String[] // array of image URLs\n  tags      String[]\n  visitedAt DateTime\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"journal_entries\")\n}\n\n// ─── AI Results ──────────────────────────────────────────\nmodel AiCompassResult {\n  id        String   @id @default(cuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  query     String\n  mood      String[]\n  result    Json // AI response data\n  createdAt DateTime @default(now())\n\n  @@map(\"ai_compass_results\")\n}\n",
